      $PSStyle.Formatting.Warning = "$e[38;2;224;169;109m"
      $PSStyle.Formatting.Verbose = "$e[38;2;184;189;240m"
      $PSStyle.Formatting.Debug = "$e[38;2;134;140;151m"
