      if ($formatting['FeedbackName']) { $PSStyle.Formatting.FeedbackName = "$e[38;2;120;162;213m" }
      if ($formatting['FeedbackText']) { $PSStyle.Formatting.FeedbackText = "$e[39m" }
      if ($formatting['FeedbackAction']) { $PSStyle.Formatting.FeedbackAction = "$e[38;2;155;202;217m" }
